import tarfile
import os
from flask import Flask, request

app = Flask(__name__)
UPLOAD_DIR = "/tmp/uploads"

def is_safe_member(member):
    # 仅允许字母数字、下划线和点号，防止路径穿越
    if not member.name or not all(c.isalnum() or c in '_.' for c in member.name):
        return False
    # 确保成员名不以 / 或 .. 开头
    if member.name.startswith('/') or member.name.startswith('..'):
        return False
    return True

def extract_tar_safely(tar_path, target_dir):
    with tarfile.open(tar_path) as tar:
        for member in tar.getmembers():
            if not is_safe_member(member):
                raise ValueError(f"Unsafe member: {member.name}")
        # 使用 ignore_prefix 防止路径穿越
        tar.extractall(path=target_dir, members=[m for m in tar.getmembers() if is_safe_member(m)])

@app.route("/extract_tar", methods=["POST"])
def extract_tar():
    raw = request.get_data()
    tar_path = os.path.join(UPLOAD_DIR, "upload.tar")
    with open(tar_path, "wb") as f:
        f.write(raw)
    try:
        extract_tar_safely(tar_path, UPLOAD_DIR)
    except Exception as e:
        return str(e), 400
    return "Extracted"
